# Physics, heat, oscillations, waves and optics (10+2 CBSE): thermal
# properties, thermodynamics, kinetic theory, oscillations, sound, ray optics,
# wave optics.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Thermal properties", "A temperature of 77 °F is equal to",
      ["25 °C", "45 °C", "43 °C", "81 °C"],
      "C = (F - 32) x 5 / 9 = (77 - 32) x 5 / 9 = 45 x 5 / 9 = 25 °C. 45 °C forgets to multiply by 5/9, 43 °C multiplies 77 by 5/9 without first subtracting 32, and 81 °C multiplies 45 by 9/5 instead of 5/9."),
    S(1, 2, "Thermodynamics", "An ideal gas expands isothermally. What is the change in its internal energy?",
      ["Zero", "Equal to the heat supplied", "Equal to the work done", "Equal to twice the work done"],
      "The internal energy of an ideal gas depends only on its temperature. In an isothermal process the temperature is constant, so ΔU = 0 and all the heat supplied is used to do work."),
    S(1, 2, "Thermodynamics", "A Carnot engine works between a source at 500 K and a sink at 300 K. What is its efficiency?",
      ["40%", "60%", "67%", "0.4%"],
      "Efficiency = 1 - T₂/T₁ = 1 - 300/500 = 0.4 = 40%. 60% is T₂/T₁ itself, 67% divides the 200 K difference by the sink temperature instead of the source, and 0.4% forgets that 0.4 is already 40%."),
    S(1, 1, "Oscillations", "The time period of a simple pendulum of small amplitude does NOT depend on",
      ["the mass of the bob", "the length of the string", "the acceleration due to gravity", "the place where it swings"],
      r"$T = 2\pi\sqrt{L/g}$. It depends on the length and on g, which changes from place to place, but not on the mass of the bob."),
    S(1, 1, "Waves", "A sound wave has a frequency of 500 Hz and a wavelength of 0.68 m. What is its speed?",
      ["340 m/s", "735 m/s", "170 m/s", "680 m/s"],
      "Speed = frequency x wavelength = 500 x 0.68 = 340 m/s. 735 m/s divides 500 by 0.68 instead of multiplying."),
    S(1, 2, "Ray optics", "What is the power of a convex lens of focal length 40 cm?",
      ["+2.5 D", "+0.4 D", "-0.4 D", "-2.5 D"],
      "Power = 1 / f in metres = 1 / 0.4 = +2.5 dioptres. A convex lens is converging, so its power is positive. +0.4 D uses the focal length in metres instead of its reciprocal, and the negative values belong to a concave (diverging) lens."),
    S(1, 1, "Ray optics", "Optical fibres carry light signals over long distances by",
      ["total internal reflection", "diffraction", "polarisation", "dispersion"],
      "Light inside the fibre's core strikes its boundary with the cladding at more than the critical angle, so it is totally reflected again and again and stays inside the fibre."),

    # ---------- Practice Test 2 ----------
    S(2, 2, "Thermal properties", "How much heat is needed to raise the temperature of 2 kg of water by 10 °C? (Specific heat of water = 4200 J/kg °C)",
      ["84 kJ", "42 kJ", "8.4 kJ", "0.84 kJ"],
      "Q = mcΔT = 2 x 4200 x 10 = 84,000 J = 84 kJ. 42 kJ leaves out the mass of 2 kg, and 8.4 kJ and 0.84 kJ slip a power of ten when converting joules to kilojoules."),
    S(2, 1, "Thermal properties", "Heat from the Sun reaches the Earth mainly by",
      ["radiation", "conduction", "convection", "evaporation"],
      "Space between the Sun and the Earth is nearly empty, so there is no medium for conduction or convection. Heat travels as electromagnetic radiation, which needs no medium."),
    S(2, 2, "Kinetic theory of gases", "A gas occupies 6 L at a pressure of 2 atm. At the same temperature, what volume will it occupy at 3 atm?",
      ["4 L", "9 L", "3 L", "6 L"],
      "Boyle's law: P₁V₁ = P₂V₂, so V₂ = 2 x 6 / 3 = 4 L. 9 L treats volume as rising with pressure, which is the opposite of Boyle's law."),
    S(2, 1, "Kinetic theory of gases", "According to the kinetic theory of gases, the average kinetic energy of a gas molecule is directly proportional to",
      ["the absolute temperature of the gas", "the volume of the gas", "the square of the pressure", "the mass of the container"],
      "Average kinetic energy per molecule = (3/2) kT, where T is the absolute temperature in kelvin. Doubling the absolute temperature doubles the average kinetic energy."),
    S(2, 2, "Waves", "The pitch of an ambulance siren seems higher as the ambulance approaches a listener. This is due to",
      ["the Doppler effect", "the reflection of sound", "resonance", "the interference of sound"],
      "When a source moves towards a listener, more wavefronts reach the listener each second, so the apparent frequency (pitch) is higher. This change with relative motion is the Doppler effect."),
    S(2, 2, "Ray optics", "The refractive index of water is 4/3. What is the speed of light in water? (Speed of light in vacuum = 3 x 10⁸ m/s)",
      [r"$2.25 \times 10^8$ m/s", r"$4 \times 10^8$ m/s", r"$1.33 \times 10^8$ m/s", r"$3 \times 10^8$ m/s"],
      r"$n = c / v$, so $v = c / n = 3 \times 10^8 \div \frac{4}{3} = 2.25 \times 10^8$ m/s. Light slows down in a denser medium; $4 \times 10^8$ m/s multiplies by n instead of dividing, and $3 \times 10^8$ m/s is its speed in vacuum."),
    S(2, 2, "Wave optics", "In Young's double-slit experiment, light of wavelength 600 nm falls on slits 0.5 mm apart, and the screen is 1 m away. What is the fringe width?",
      ["1.2 mm", "0.6 mm", "12 mm", "2.4 mm"],
      "β = λD / d = (600 x 10⁻⁹ x 1) / (0.5 x 10⁻³) = 1.2 x 10⁻³ m = 1.2 mm. 0.6 mm and 2.4 mm come from doubling or halving the slit separation, and 12 mm slips a power of ten."),

    # ---------- Drill only ----------
    S(0, 1, "Thermal properties", "Which temperature is equal to 0 K (absolute zero)?",
      ["-273.15 °C", "0 °C", "-100 °C", "273.15 °C"],
      "K = °C + 273.15, so 0 K = -273.15 °C. Water freezes at 0 °C, which is 273.15 K; +273.15 °C would be 546.3 K."),
    S(0, 2, "Thermodynamics", "In an adiabatic process,",
      ["no heat enters or leaves the system", "the temperature stays constant", "the pressure stays constant", "the volume stays constant"],
      "Adiabatic means no heat exchange with the surroundings (Q = 0). Constant temperature is isothermal, constant pressure isobaric and constant volume isochoric."),
    S(0, 1, "Thermal properties", "Small gaps are left between lengths of railway track mainly because",
      ["the rails expand when they get hot", "the gaps make the train run quieter", "the gaps let rainwater drain away", "the rails shrink as they wear out"],
      "Steel expands on heating. Without gaps, the rails would push against each other on hot days and could buckle."),
    S(0, 1, "Oscillations", "If the length of a simple pendulum is made four times as long, its time period becomes",
      ["twice as long", "four times as long", "half as long", "sixteen times as long"],
      r"$T \propto \sqrt{L}$, so multiplying the length by 4 multiplies the period by $\sqrt{4} = 2$."),
    S(0, 2, "Waves", "Two tuning forks of frequencies 256 Hz and 260 Hz are sounded together. How many beats are heard each second?",
      ["4", "8", "258", "516"],
      "Beat frequency = difference of the two frequencies = 260 - 256 = 4 beats per second. 258 Hz is their average, the pitch of the combined sound, and 516 is their sum."),
    S(0, 2, "Waves", "A soldier fires a starting pistol and hears the echo from a distant building 1.5 s later. If sound travels at 340 m/s, how far away is the building?",
      ["255 m", "510 m", "170 m", "227 m"],
      "In 1.5 s the sound travels 340 x 1.5 = 510 m, to the building and back, so the building is 510 / 2 = 255 m away. 510 m forgets the round trip, 170 m halves the speed only, and 227 m divides 340 by 1.5."),
    S(0, 1, "Ray optics", "A ray of light passes through a glass prism in the position of minimum deviation. Inside the prism, the ray travels",
      ["parallel to the base of the prism", "along the normal to the first face", "at right angles to the base", "along the second face of the prism"],
      "At minimum deviation the ray passes symmetrically through the prism: the angle of incidence equals the angle of emergence, and the refracted ray inside the prism is parallel to the base."),
    S(0, 1, "Ray optics", "A short-sighted (myopic) person cannot see clearly beyond 2 m (the far point). What is the power of the lens needed to correct this?",
      ["-0.5 D", "+0.5 D", "-2 D", "+2 D"],
      "The lens must form an image of a very distant object at the far point, so it is a concave lens of focal length -2 m. P = 1 / f = 1 / (-2) = -0.5 D. A short-sighted eye needs a diverging lens, so the positive powers are wrong, and -2 D uses the focal length in metres instead of its reciprocal."),
]
